1	import type { Metadata } from "next";
2	import { notFound } from "next/navigation";
3	import { db } from "@/lib/db";
4	import { UseCaseLanding } from "@/components/marketing/UseCaseLanding";
5	import { APP_URL } from "@/components/marketing/StructuredData";
6	import {
7	  findCombo,
8	  buildLanding,
9	  LANDING_SLUGS,
10	  type LandingPlan,
11	} from "@/lib/marketing/locationLandings";
12	
13	/**
14	 * Programmatic "(location) (service)" marketing landing pages.
15	 *
16	 * One data-driven route renders the whole location × service matrix defined in
17	 * `lib/marketing/locationLandings.ts` — e.g. /london-vps-hosting,
18	 * /toronto-web-hosting, /frankfurt-game-server-hosting. Any slug not in the
19	 * matrix falls through to a 404, so this catch-all never shadows the
20	 * hand-written marketing pages (which win at request time anyway) or invents
21	 * doorway pages. Real DB plans feed the pricing grid and Product rich-result.
22	 */
23	
24	export const dynamic = "force-dynamic";
25	
26	// Pre-declare the known slugs so Next can enumerate the matrix; unknown slugs
27	// are rejected in the page/metadata via notFound().
28	export function generateStaticParams(): Array<{ slug: string }> {
29	  return LANDING_SLUGS.map((slug) => ({ slug }));
30	}
31	
32	async function loadPlans(): Promise<LandingPlan[]> {
33	  return db.plan.findMany({
34	    where: { active: true },
35	    orderBy: { sortOrder: "asc" },
36	  });
37	}
38	
39	export async function generateMetadata({
40	  params,
41	}: {
42	  params: Promise<{ slug: string }>;
43	}): Promise<Metadata> {
44	  const { slug } = await params;
45	  const combo = findCombo(slug);
46	  if (!combo) return {};
47	
48	  const plans = await loadPlans();
49	  const built = buildLanding(combo, plans);
50	  const url = `${APP_URL}/${slug}`;
51	
52	  return {
53	    title: built.metaTitle,
54	    description: built.metaDescription,
55	    alternates: { canonical: `/${slug}` },
56	    openGraph: {
57	      type: "article",
58	      title: built.ogTitle,
59	      description: built.ogDescription,
60	      url,
61	    },
62	    twitter: {
63	      card: "summary_large_image",
64	      title: built.ogTitle,
65	      description: built.ogDescription,
66	    },
67	  };
68	}
69	
70	export default async function LocationServiceLandingPage({
71	  params,
72	}: {
73	  params: Promise<{ slug: string }>;
74	}) {
75	  const { slug } = await params;
76	  const combo = findCombo(slug);
77	  if (!combo) notFound();
78	
79	  const plans = await loadPlans();
80	  const built = buildLanding(combo, plans);
81	  const url = `${APP_URL}/${slug}`;
82	
83	  // BreadcrumbList — helps Google render the Home › <Page> trail and reinforces
84	  // the page's place in the site. FAQ + Product JSON-LD are emitted by
85	  // UseCaseLanding from the same content, so all three rich results are covered.
86	  const breadcrumb = {
87	    "@context": "https://schema.org",
88	    "@type": "BreadcrumbList",
89	    itemListElement: [
90	      { "@type": "ListItem", position: 1, name: "Home", item: APP_URL },
91	      { "@type": "ListItem", position: 2, name: built.breadcrumbName, item: url },
92	    ],
93	  };
94	
95	  return (
96	    <>
97	      <script
98	        type="application/ld+json"
99	        dangerouslySetInnerHTML={{ __html: JSON.stringify(breadcrumb) }}
100	      />
101	      <UseCaseLanding content={built.content} plans={plans} />
102	    </>
103	  );
104	}
