import type { Metadata } from "next";
import { ComparePageLayout } from "@/components/marketing/ComparePageLayout";
import type { CompareRow } from "@/components/marketing/CompareTable";
import { getVpsPriceBand, type VpsPriceBand } from "@/lib/vps-price-band";

const APP_URL = process.env.APP_URL ?? "https://nxeon.cloud";

export const metadata: Metadata = {
  title: "Nxeon vs Bluehost — an honest VPS comparison",
  description:
    "How Nxeon's developer VPS compares to Bluehost: full root on NVMe/ZFS near Asia, game servers, dedicated IPv4 and flat pricing — and where Bluehost's managed WordPress hosting fits.",
  alternates: { canonical: "/vps-vs-bluehost" },
  openGraph: {
    type: "article",
    title: "Nxeon vs Bluehost — an honest VPS comparison",
    description:
      "A developer-first VPS near Asia versus a managed WordPress and shared-hosting brand. An honest look at where each one fits.",
    url: `${APP_URL}/vps-vs-bluehost`,
  },
};

export const dynamic = "force-dynamic";

const ROWS = (b: VpsPriceBand | null): CompareRow[] => [
  { feature: "Best for", nxeon: "Developers wanting full root on a real box near Asia", other: "Beginners launching a managed WordPress or shared-hosting site" },
  { feature: "Product focus", nxeon: "A single, developer-first NVMe VPS", other: "Managed WordPress and shared hosting, with VPS/dedicated options" },
  { feature: "Location focus", nxeon: "Single Singapore node — low APAC latency", other: "Primarily US-based data centres" },
  { feature: "Storage", nxeon: "Enterprise NVMe SSD on a self-healing ZFS mirror", other: "SSD storage; specifics vary by plan tier" },
  { feature: "Root access", nxeon: "Full root over SSH on every plan", other: "Root on their VPS/dedicated tiers; not on shared or managed WordPress" },
  { feature: "Game servers", nxeon: "First-class — Minecraft, Rust, Valheim, Palworld, CS2 and more, one-click", other: "Not a focus — you'd self-host on a VPS/dedicated box" },
  { feature: "Dedicated IPv4", nxeon: "Included with every plan", other: "Included on VPS/dedicated; typically an add-on on shared plans" },
  { feature: "Domains", nxeon: "Register & manage domains in the same dashboard", other: "Domain registration available; often a first-year promo with paid renewal" },
  { feature: "Free migration", nxeon: "One-click, read-only, no DB passwords — included free", other: "WordPress migration offered; terms and automation vary by plan" },
  {
    feature: "Pricing model",
    nxeon: b ? `Simple all-in monthly plans, ${b.rangeLabel}, no card to sign up` : "Simple all-in monthly plans, no card to sign up",
    other: "Promotional intro rates that renew higher — always check the renewal terms",
  },
];

const CHOOSE_NXEON = [
  "You want full root on a real NVMe/ZFS box near Asia",
  "You're running apps, Docker or game servers — not just a website",
  "You value flat, all-in pricing with no renewal surprises",
  "You'd like a free one-click migration off your current host",
];
const CHOOSE_OTHER = [
  "You want managed WordPress hosting with a guided, click-only setup",
  "Your audience is mostly in the US",
  "You'd rather never touch a command line",
  "You want bundled email and a familiar cPanel-style beginner flow",
];

const FAQ = (b: VpsPriceBand | null) => [
  {
    q: "Is Nxeon a good Bluehost alternative?",
    a: "If you've outgrown shared hosting and want a real server with full root — for a web app, Docker, a game server or a self-hosted stack — Nxeon is a focused developer VPS. Bluehost is aimed at beginners running managed WordPress or shared sites, so if you want a guided, click-only setup and never want a terminal, it may suit you better.",
  },
  {
    q: "Can I run WordPress on Nxeon?",
    a: "Yes. WordPress is available as a one-click app, and you get full root to tune PHP, caching and the database yourself on NVMe/ZFS storage. The difference is control: Bluehost manages the WordPress layer for you, while Nxeon gives you the whole box to run it your way.",
  },
  {
    q: "Where are the servers located?",
    a: "Nxeon runs a single node in Singapore, which keeps latency low for Asia-Pacific visitors. Bluehost is primarily US-based, so if most of your audience is in North America, weigh that physical distance either way.",
  },
  {
    q: "What does Nxeon cost?",
    a: b
      ? `Simple all-in monthly plans from ${b.fromLabel} (${b.fromName}) to ${b.toLabel} (${b.toName}), each with a dedicated IPv4 included and no credit card required to sign up. The price you see is the price checkout charges — no renewal step-up.`
      : "Simple all-in monthly plans with a dedicated IPv4 included and no credit card required to sign up. The price you see is the price checkout charges.",
  },
];

export default async function VpsVsBluehost() {
  const band = await getVpsPriceBand();
  return (
    <ComparePageLayout
      competitor="Bluehost"
      competitorSlug="bluehost"
      heroTitle="Nxeon vs"
      heroHighlight="Bluehost"
      heroSub="Bluehost is built for beginners launching a managed WordPress or shared-hosting site. Nxeon is a developer-first NVMe VPS on a self-healing ZFS mirror — full root, game servers and APAC latency, with flat, all-in pricing. Here's how they line up."
      fromLabel={band?.fromLabel}
      rows={ROWS(band)}
      chooseNxeon={CHOOSE_NXEON}
      chooseOther={CHOOSE_OTHER}
      faq={FAQ(band)}
    />
  );
}
